window.kbPageData["views/entry/k-d4cb61d31f99b606"] = {"key":"entry/k-d4cb61d31f99b606","state":{"route":"entry/k-d4cb61d31f99b606"},"node":{"id":"k-d4cb61d31f99b606","mode":"k","title":"种质资源国家主权","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["国家对种质资源享有主权"],"qs":["江苏 2024 C类 行测#6"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"国家对种质资源享有主权。单位或个人向境外提供种质资源，或者与境外机构、个人合作研究利用种质资源，应当报国务院有关主管部门批准，并同时提交国家共享惠益的方案。","review":{"definition":"国家对种质资源享有主权。单位或个人向境外提供种质资源，或者与境外机构、个人合作研究利用种质资源，应当报国务院有关主管部门批准，并同时提交国家共享惠益的方案。","explanation":"题目要求选出不正确的说法。种植者和育种者可以参与种质资源的利用，但利用者身份不改变国家主权的归属。D项把主权归给种植者和育种者，因此应选D。","references":[],"evidence":"国家对种质资源享有主权。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#6":{"paper":"江苏 2024 C类 行测","n":6,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",2],"asrc":["02d6b49839583bdaf297.pdf",2],"card":"98551fe75e468e8d61347276","links":[{"id":"k-d4cb61d31f99b606","role":"直接考查","why":"《中华人民共和国种子法》第十一条明确规定了种质资源的主权归属。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d4cb61d31f99b606":[["江苏 2024 C类 行测#6"]]}};
